(741, 'elaborate', '/ɪˈlæbərət/', 'adjective / verb', '{"zh-TW":["精心的；詳述"],"en":["detailed and complicated; to explain in more detail"]}', NULL, 'elaborate on/plan', '[{"en":"Could you elaborate on your proposal?","zh-TW":"你能詳細說明你的提案嗎？"},{"en":"They developed an elaborate marketing strategy.","zh-TW":"他們制定了精心的行銷策略。"}]', '{"noun":"elaboration","verb":"elaborate","adjective":"elaborate"}', NULL, 3, 741),
(742, 'elect', '/ɪˈlekt/', 'verb', '{"zh-TW":["選舉；選擇"],"en":["to choose by voting"]}', NULL, 'elect a president/chairperson', '[{"en":"She was elected as the new chairperson.","zh-TW":"她被選為新主席。"},{"en":"Members elect the board annually.","zh-TW":"成員每年選舉董事會。"}]', '{"noun":"election","verb":"elect","adjective":"elected/electoral"}', NULL, 2, 742),
(743, 'elective', '/ɪˈlɛktɪv/', 'noun', '{"zh-TW":["選修課"],"en":["a course that students can choose to take"]}', NULL, 'elective course / take an elective', '[{"en":"Art is an elective at our school.","zh-TW":"藝術在我們學校是選修課。"},{"en":"Students must take two electives.","zh-TW":"學生必須選修兩門選修課。"}]', NULL, NULL, 3, 743),
(744, 'element', '/ˈelɪmənt/', 'noun', '{"zh-TW":["要素；元素"],"en":["a component or part of something"]}', NULL, 'key/essential element', '[{"en":"Trust is a key element of teamwork.","zh-TW":"信任是團隊合作的關鍵要素。"},{"en":"The plan has several important elements.","zh-TW":"該計畫有幾個重要的要素。"}]', '{"noun":"element","adjective":"elementary"}', NULL, 3, 744),
(745, 'elevate', '/ˈelɪveɪt/', 'verb', '{"zh-TW":["提升；提高"],"en":["to raise to a higher position or level"]}', NULL, 'elevate standards/status', '[{"en":"The promotion elevated her to senior manager.","zh-TW":"升遷使她晉升為高級經理。"},{"en":"We aim to elevate customer experience.","zh-TW":"我們的目標是提升客戶體驗。"}]', '{"noun":"elevation/elevator","verb":"elevate","adjective":"elevated"}', NULL, 3, 745),
(746, 'eligible', '/ˈelɪdʒəbəl/', 'adjective', '{"zh-TW":["合格的；有資格的"],"en":["meeting the conditions to do or receive something"]}', NULL, 'eligible for/to', '[{"en":"All full-time employees are eligible for benefits.","zh-TW":"所有全職員工都有資格享受福利。"},{"en":"You must be 18 to be eligible to vote.","zh-TW":"你必須年滿18歲才有投票資格。"}]', '{"noun":"eligibility","adjective":"eligible"}', NULL, 3, 746),
(747, 'eliminate', '/ɪˈlɪmɪneɪt/', 'verb', '{"zh-TW":["消除；淘汰"],"en":["to completely remove or get rid of"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"limin","meaning":"threshold (門檻)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使超出門檻之外，即「淘汰」。"}', 'eliminate waste/errors; eliminate waste / eliminate the possibility', '[{"en":"We need to eliminate unnecessary costs.","zh-TW":"我們需要消除不必要的成本。"},{"en":"The company eliminated 200 positions.","zh-TW":"公司裁撤了200個職位。"},{"en":"The team was eliminated in the first round.","zh-TW":"該隊在第一輪就被淘汰了。"}]', '{"noun":"elimination","verb":"eliminate"}', NULL, 3, 747),
(748, 'embarrassed', '/ɪmˈbærəst/', 'adjective', '{"zh-TW":["尷尬的；難為情的"],"en":["feeling ashamed or shy"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"barrass","meaning":"bar/obstruct (阻礙)"},"suffix":{"text":"-ed","meaning":"feeling (感受)"},"logic":"感覺被阻礙住的，即「尷尬的」。"}', 'feel embarrassed / embarrassed about', '[{"en":"He was embarrassed by his mistake.","zh-TW":"他因犯錯而感到尷尬。"},{"en":"She felt embarrassed in front of everyone.","zh-TW":"她在眾人面前感到難為情。"}]', '{"noun":"embarrassment","adjective":"embarrassing","verb":"embarrass"}', NULL, 4, 748),
(749, 'embrace', '/ɪmˈbreɪs/', 'verb', '{"zh-TW":["擁抱；接受"],"en":["to accept willingly; to hold closely"]}', NULL, 'embrace change/technology', '[{"en":"Companies must embrace new technology.","zh-TW":"企業必須擁抱新技術。"},{"en":"She embraced the opportunity eagerly.","zh-TW":"她熱切地接受了這個機會。"}]', '{"noun":"embrace","verb":"embrace"}', NULL, 3, 749);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(750, 'emerge', '/ɪˈmɜːrdʒ/', 'verb', '{"zh-TW":["出現；浮現"],"en":["to come into view; to become known","to come into view or existence"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"merge","meaning":"dip/plunge (浸入)"},"logic":"從水中浮出，即「出現」。"}', 'emerge as/from; emerge from / emerging market / emerge as', '[{"en":"New competitors are emerging in the market.","zh-TW":"市場上出現了新的競爭者。"},{"en":"The company emerged as a market leader.","zh-TW":"該公司成為市場領導者。"},{"en":"New evidence emerged during the investigation.","zh-TW":"調查期間浮現了新證據。"},{"en":"She emerged as the leading candidate.","zh-TW":"她脫穎而出成為領先的候選人。"}]', '{"noun":"emergence","verb":"emerge","adjective":"emerging/emergent"}', NULL, 2, 750),
(751, 'emergency', '/ɪˈmɜːrdʒənsi/', 'noun', '{"zh-TW":["緊急情況"],"en":["a serious unexpected situation requiring immediate action"]}', NULL, 'in case of emergency', '[{"en":"Call 911 in case of an emergency.","zh-TW":"緊急情況下請撥打911。"},{"en":"An emergency meeting was called.","zh-TW":"召開了緊急會議。"}]', '{"noun":"emergency","adjective":"emergency"}', NULL, 3, 751),
(752, 'emission', '/ɪˈmɪʃən/', 'noun', '{"zh-TW":["排放；排放物"],"en":["the production and discharge of something, especially gas"]}', NULL, 'carbon/greenhouse emissions', '[{"en":"The factory must reduce its carbon emissions.","zh-TW":"工廠必須減少碳排放。"},{"en":"Emission standards are becoming stricter.","zh-TW":"排放標準越來越嚴格。"}]', '{"noun":"emission","verb":"emit"}', NULL, 3, 752),
(753, 'emotion', '/ɪˈmoʊʃn/', 'noun', '{"zh-TW":["情緒；情感"],"en":["a strong feeling such as joy, anger, or sadness"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"mot","meaning":"move (移動)"},"suffix":{"text":"-ion","meaning":"state (狀態)"},"logic":"從內心移動出來的感覺，即「情緒」。"}', 'strong emotion / show emotion / mixed emotions', '[{"en":"She couldn''t hide her emotions.","zh-TW":"她無法隱藏自己的情緒。"},{"en":"The movie evoked strong emotions.","zh-TW":"這部電影激發了強烈的情感。"}]', '{"adjective":"emotional","adverb":"emotionally"}', NULL, 3, 753),
(754, 'empathy', '/ˈempəθi/', 'noun', '{"zh-TW":["同理心"],"en":["the ability to understand and share another''s feelings"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"path","meaning":"feeling (感受)"},"suffix":{"text":"-y","meaning":"state (狀態)"},"logic":"進入他人感受中，即「同理心」。"}', 'show empathy / lack of empathy', '[{"en":"A good therapist shows empathy toward patients.","zh-TW":"好的治療師對病人展現同理心。"},{"en":"Empathy is important in building relationships.","zh-TW":"同理心在建立關係中很重要。"}]', '{"adjective":"empathetic","verb":"empathize"}', NULL, 3, 754),
(755, 'emphasis', '/ˈemfəsɪs/', 'noun', '{"zh-TW":["強調；重點"],"en":["special importance given to something"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"phas","meaning":"show (展現)"},"suffix":{"text":"-is","meaning":"state (狀態)"},"logic":"在其中展現出重要性，即「強調」。"}', 'place/put emphasis on; place emphasis on / with emphasis / special emphasis', '[{"en":"The company places great emphasis on quality.","zh-TW":"公司非常重視品質。"},{"en":"There is growing emphasis on sustainability.","zh-TW":"對永續發展的重視日益增長。"},{"en":"The school places emphasis on creative thinking.","zh-TW":"學校強調創意思考。"},{"en":"She spoke with great emphasis.","zh-TW":"她說話時特別加重語氣。"}]', '{"noun":"emphasis","verb":"emphasize","adjective":"emphatic"}', NULL, 3, 755),
(756, 'employ', '/ɪmˈplɔɪ/', 'verb', '{"zh-TW":["僱用；使用","雇用；運用"],"en":["to give work to someone; to use","to give work to someone","to make use of"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"ploy","meaning":"fold/use (使用)"},"logic":"把人用進來，即「雇用」。"}', 'employ staff/methods; employ staff / employ a strategy / currently employed', '[{"en":"The company employs over 5,000 people.","zh-TW":"該公司僱用了5000多人。"},{"en":"We employ various strategies to boost sales.","zh-TW":"我們使用各種策略來促進銷售。"},{"en":"The company employs over 500 people.","zh-TW":"公司雇用超過500人。"},{"en":"She employed a new strategy to solve the problem.","zh-TW":"她運用了新策略來解決問題。"}]', '{"noun":"employment/employee/employer","verb":"employ","noun2":"employee","noun3":"employer"}', NULL, 2, 756),
(757, 'empower', '/ɪmˈpaʊər/', 'verb', '{"zh-TW":["賦予權力；使能夠"],"en":["to give someone authority or confidence"]}', NULL, 'empower employees/women', '[{"en":"The training empowers employees to make decisions.","zh-TW":"培訓賦予員工做決定的能力。"},{"en":"Technology empowers small businesses to compete.","zh-TW":"技術使小企業能夠參與競爭。"}]', '{"noun":"empowerment","verb":"empower"}', NULL, 3, 757),
(758, 'empty', '/ˈɛmpti/', 'adjective', '{"zh-TW":["空的"],"en":["containing nothing; not filled"]}', NULL, 'empty space / empty promise', '[{"en":"The meeting room is empty now.","zh-TW":"會議室現在是空的。"},{"en":"Don''t make empty promises.","zh-TW":"別做空洞的承諾。"}]', '{"adjective":"empty","verb":"empty","noun":"emptiness"}', NULL, 2, 758),
(759, 'enable', '/ɪˈneɪbəl/', 'verb', '{"zh-TW":["使能夠；啟用"],"en":["to make possible or allow","to make possible or provide the means for"]}', '{"prefix":{"text":"en-","meaning":"make (使)"},"root":{"text":"able","meaning":"able (能夠)"},"logic":"使其能夠，即「使能夠」。"}', 'enable + 人 + to; enable access / enable growth', '[{"en":"The software enables users to track expenses.","zh-TW":"該軟體使用戶能夠追蹤支出。"},{"en":"This funding will enable further research.","zh-TW":"這筆資金將使進一步研究成為可能。"},{"en":"Technology enables people to work from home.","zh-TW":"科技使人們能在家工作。"},{"en":"The grant enabled her to continue her research.","zh-TW":"這筆補助使她能繼續研究。"}]', '{"verb":"enable","adjective":"enabling"}', NULL, 2, 759),
(760, 'enact', '/ɪˈnækt/', 'verb', '{"zh-TW":["制定；頒布"],"en":["to make a bill into law"]}', NULL, 'enact legislation/a policy', '[{"en":"The government enacted new environmental regulations.","zh-TW":"政府制定了新的環境法規。"},{"en":"The law was enacted in 2020.","zh-TW":"該法律於2020年頒布。"}]', '{"noun":"enactment","verb":"enact"}', NULL, 2, 760),
(761, 'encounter', '/ɪnˈkaʊntər/', 'verb / noun', '{"zh-TW":["遭遇；碰到","遭遇；偶遇"],"en":["to unexpectedly meet or face","to unexpectedly meet or face something"]}', '{"prefix":{"text":"en-","meaning":"in (在)"},"root":{"text":"counter","meaning":"against (對面)"},"logic":"在對面碰上，即「遭遇」。"}', 'encounter difficulties/problems; encounter problems / encounter difficulties', '[{"en":"We encountered several problems during installation.","zh-TW":"我們在安裝過程中遇到了幾個問題。"},{"en":"It was her first encounter with the CEO.","zh-TW":"這是她第一次與執行長碰面。"},{"en":"We encountered several problems along the way.","zh-TW":"我們一路上遇到了幾個問題。"},{"en":"I encountered an old friend at the airport.","zh-TW":"我在機場偶遇一位老朋友。"}]', '{"noun":"encounter","verb":"encounter"}', NULL, 3, 761),
(762, 'encourage', '/ɪnˈkɜːrɪdʒ/', 'verb', '{"zh-TW":["鼓勵；促進"],"en":["to give support or confidence"]}', NULL, 'encourage + 人 + to', '[{"en":"The manager encouraged her team to innovate.","zh-TW":"經理鼓勵她的團隊創新。"},{"en":"Low interest rates encourage borrowing.","zh-TW":"低利率鼓勵借貸。"}]', '{"noun":"encouragement","verb":"encourage","adjective":"encouraging"}', NULL, 3, 762),
(763, 'encryption', '/ɪnˈkrɪpʃən/', 'noun', '{"zh-TW":["加密"],"en":["the process of converting data into a secret code"]}', NULL, 'data encryption / end-to-end encryption', '[{"en":"The message uses end-to-end encryption.","zh-TW":"訊息使用端對端加密。"},{"en":"Encryption protects your data.","zh-TW":"加密保護你的資料。"}]', '{"verb":"encrypt","adjective":"encrypted"}', NULL, 4, 763),
(764, 'end', '/ɛnd/', 'noun', '{"zh-TW":["結束；末端"],"en":["the final part","to finish"]}', NULL, 'at the end / end up', '[{"en":"At the end of the month, we review performance.","zh-TW":"月底我們會檢討績效。"},{"en":"The contract ends next year.","zh-TW":"合約明年到期。"}]', '{"noun":"end","verb":"end","adjective":"endless","noun2":"ending"}', NULL, 1, 764),
(765, 'endorse', '/ɪnˈdɔːrs/', 'verb', '{"zh-TW":["背書；認可"],"en":["to publicly approve or support"]}', NULL, 'endorse a product/candidate', '[{"en":"Several celebrities endorsed the brand.","zh-TW":"多位名人為該品牌背書。"},{"en":"The board endorsed the new strategy.","zh-TW":"董事會認可了新策略。"}]', '{"noun":"endorsement","verb":"endorse"}', NULL, 3, 765),
(766, 'enemy', '/ˈɛnəmi/', 'noun', '{"zh-TW":["敵人；敵方"],"en":["a person who is hostile to another"]}', NULL, 'worst enemy / make enemies', '[{"en":"Procrastination is your worst enemy.","zh-TW":"拖延是你最大的敵人。"},{"en":"Don''t make enemies in the industry.","zh-TW":"別在業界樹敵。"}]', '{"noun":"enemy","noun2":"enmity"}', NULL, 2, 766),
(767, 'enforce', '/ɪnˈfɔːrs/', 'verb', '{"zh-TW":["執行；強制","執行；強制實施"],"en":["to compel compliance with a law or rule","to make sure a law or rule is obeyed"]}', NULL, 'enforce regulations/rules; enforce the law / strictly enforced', '[{"en":"The police enforce traffic laws.","zh-TW":"警察執行交通法規。"},{"en":"The contract will be strictly enforced.","zh-TW":"合約將被嚴格執行。"},{"en":"Police enforce traffic laws.","zh-TW":"警察執行交通法規。"},{"en":"The rules are strictly enforced.","zh-TW":"規則被嚴格執行。"}]', '{"noun":"enforcement","verb":"enforce","adjective":"enforceable"}', NULL, 3, 767),
(768, 'engage', '/ɪnˈɡeɪdʒ/', 'verb', '{"zh-TW":["參與；僱用","參與；吸引"],"en":["to participate; to attract attention","to participate or become involved","to attract someone''s attention"]}', '{"prefix":{"text":"en-","meaning":"in (進入)"},"root":{"text":"gage","meaning":"pledge (承諾)"},"logic":"進入承諾參與，即「參與」。"}', 'engage in/with; engage in / engage with / engage employees', '[{"en":"The company engages in sustainable practices.","zh-TW":"公司參與永續實踐。"},{"en":"We need to engage more customers online.","zh-TW":"我們需要在線上吸引更多客戶。"},{"en":"Students are encouraged to engage in discussions.","zh-TW":"鼓勵學生參與討論。"},{"en":"The presentation engaged the entire audience.","zh-TW":"報告吸引了全場觀眾。"}]', '{"noun":"engagement","verb":"engage","adjective":"engaging/engaged"}', NULL, 2, 768),
(769, 'engine', '/ˈɛndʒɪn/', 'noun', '{"zh-TW":["引擎；發動機"],"en":["a machine that converts energy into motion"]}', NULL, 'search engine / engine of growth', '[{"en":"Use a search engine to find information.","zh-TW":"使用搜尋引擎查找資訊。"},{"en":"Technology is the engine of growth.","zh-TW":"科技是成長的引擎。"}]', '{"noun":"engine","noun2":"engineer","noun3":"engineering"}', NULL, 2, 769),
(770, 'enhance', '/ɪnˈhæns/', 'verb', '{"zh-TW":["增強；提高","增強；提升"],"en":["to improve the quality or value of","to improve the quality or value of something"]}', '{"prefix":{"text":"en-","meaning":"make (使)"},"root":{"text":"hance","meaning":"high (高)"},"logic":"使其提高，即「增強」。"}', 'enhance performance/productivity; enhance performance / enhance quality / enhance the experience', '[{"en":"The update will enhance system performance.","zh-TW":"更新將增強系統性能。"},{"en":"Training enhances employee productivity.","zh-TW":"培訓提高員工生產力。"},{"en":"This software enhances image quality.","zh-TW":"這個軟體增強了影像品質。"},{"en":"The new features enhance the user experience.","zh-TW":"新功能提升了使用者體驗。"}]', '{"noun":"enhancement","verb":"enhance"}', NULL, 3, 770),
(771, 'enjoy', '/ɪnˈdʒɔɪ/', 'verb', '{"zh-TW":["享受；喜歡"],"en":["to get pleasure from something"]}', NULL, 'enjoy doing / enjoy the benefits', '[{"en":"I enjoy working with this team.","zh-TW":"我喜歡和這個團隊一起工作。"},{"en":"Members enjoy special benefits.","zh-TW":"會員享有特殊福利。"}]', '{"verb":"enjoy","noun":"enjoyment","adjective":"enjoyable"}', NULL, 2, 771),
(772, 'enormous', '/ɪˈnɔːrməs/', 'adjective', '{"zh-TW":["巨大的"],"en":["very large in size, quantity, or extent","very large in size or quantity"]}', '{"prefix":{"text":"e-","meaning":"out (超出)"},"root":{"text":"norm","meaning":"rule/standard (標準)"},"suffix":{"text":"-ous","meaning":"having (具有)"},"logic":"超出正常標準的，即「巨大的」。"}', 'enormous amount/potential; enormous amount / enormous pressure / enormous success', '[{"en":"The project requires an enormous investment.","zh-TW":"該項目需要巨額投資。"},{"en":"There is enormous potential for growth.","zh-TW":"有巨大的增長潛力。"},{"en":"The project requires an enormous amount of work.","zh-TW":"這個專案需要大量的工作。"},{"en":"The concert was an enormous success.","zh-TW":"音樂會獲得了巨大的成功。"}]', '{"adjective":"enormous","adverb":"enormously"}', NULL, 3, 772),
(773, 'enough', '/ɪˈnʌf/', 'adjective', '{"zh-TW":["足夠的"],"en":["as much as is needed"]}', NULL, 'good enough / not enough', '[{"en":"We don''t have enough staff for this project.","zh-TW":"我們沒有足夠的人手做這個專案。"},{"en":"Is this good enough?","zh-TW":"這樣夠好嗎？"}]', '{"adjective":"enough","adverb":"enough"}', NULL, 2, 773),
(774, 'enroll', '/ɪnˈroʊl/', 'verb', '{"zh-TW":["註冊；登記","註冊；入學"],"en":["to officially register for a course or program","to officially join a course or school"]}', NULL, 'enroll in a course/program; enroll in / enrollment period', '[{"en":"Over 500 students enrolled in the program.","zh-TW":"超過500名學生註冊了該計畫。"},{"en":"You can enroll online.","zh-TW":"你可以在線上註冊。"},{"en":"She enrolled in a language course.","zh-TW":"她報名了一門語言課程。"},{"en":"Over 500 students enrolled this year.","zh-TW":"今年有超過500名學生入學。"}]', '{"noun":"enrollment","verb":"enroll"}', NULL, 2, 774),
(775, 'ensure', '/ɪnˈʃʊr/', 'verb', '{"zh-TW":["確保"],"en":["to make certain that something happens"]}', '{"prefix":{"text":"en-","meaning":"make (使)"},"root":{"text":"sure","meaning":"sure (確定)"},"logic":"使其確定，即「確保」。"}', 'ensure quality/safety; ensure quality / ensure safety / ensure that', '[{"en":"Please ensure all data is backed up.","zh-TW":"請確保所有資料都已備份。"},{"en":"We must ensure customer satisfaction.","zh-TW":"我們必須確保客戶滿意度。"},{"en":"Please ensure all doors are locked.","zh-TW":"請確保所有門都已上鎖。"},{"en":"We must ensure the safety of our employees.","zh-TW":"我們必須確保員工的安全。"}]', '{"verb":"ensure"}', NULL, 2, 775),
(776, 'enter', '/ˈɛntər/', 'verb', '{"zh-TW":["進入；輸入"],"en":["to go into a place","to type data"]}', NULL, 'enter the market / enter data', '[{"en":"They plan to enter the Asian market.","zh-TW":"他們計畫進入亞洲市場。"},{"en":"Please enter your password.","zh-TW":"請輸入你的密碼。"}]', '{"verb":"enter","noun":"entrance","noun2":"entry"}', NULL, 2, 776),
(777, 'enterprise', '/ˈentərpraɪz/', 'noun', '{"zh-TW":["企業；事業"],"en":["a business or company; a bold undertaking"]}', NULL, 'private/state enterprise', '[{"en":"Small enterprises drive economic growth.","zh-TW":"小型企業推動經濟增長。"},{"en":"The new enterprise launched last quarter.","zh-TW":"新企業上季度啟動了。"}]', '{"noun":"enterprise","adjective":"enterprising"}', NULL, 4, 777),
(778, 'entertainment', '/ˌɛntərˈteɪnmənt/', 'noun', '{"zh-TW":["娛樂"],"en":["activities for enjoyment"]}', NULL, 'entertainment industry / live entertainment', '[{"en":"The hotel offers nightly entertainment.","zh-TW":"飯店每晚提供娛樂節目。"},{"en":"The entertainment industry is growing.","zh-TW":"娛樂產業正在成長。"}]', '{"verb":"entertain","noun2":"entertainer","adjective":"entertaining"}', NULL, 5, 778),
(779, 'enthusiastic', '/ɪnˌθjuːziˈæstɪk/', 'adjective', '{"zh-TW":["熱情的；熱心的"],"en":["showing intense enjoyment or interest"]}', '{"prefix":{"text":"en-","meaning":"in (在內)"},"root":{"text":"thusi","meaning":"god (神)"},"suffix":{"text":"-astic","meaning":"relating to (相關的)"},"logic":"如同有神靈附體般的熱情。"}', 'enthusiastic about / enthusiastic response', '[{"en":"She is enthusiastic about her new job.","zh-TW":"她對新工作充滿熱情。"},{"en":"The audience gave an enthusiastic response.","zh-TW":"觀眾給予熱烈回應。"}]', '{"noun":"enthusiasm","adverb":"enthusiastically"}', NULL, 4, 779),
(780, 'entire', '/ɪnˈtaɪər/', 'adjective', '{"zh-TW":["整個的；全部的"],"en":["whole; complete","with no part left out; whole"]}', '{"prefix":{"text":"in-","meaning":"not (不)"},"root":{"text":"tire","meaning":"touch/diminish (觸及/削減)"},"logic":"未被削減的，即「完整的」。"}', 'the entire team/process; the entire team / the entire day / in its entirety', '[{"en":"The entire team was present at the meeting.","zh-TW":"整個團隊都出席了會議。"},{"en":"She spent the entire day on the report.","zh-TW":"她花了一整天在報告上。"},{"en":"The entire team worked overtime.","zh-TW":"整個團隊加班工作。"},{"en":"She read the entire book in one day.","zh-TW":"她一天內讀完了整本書。"}]', '{"adjective":"entire","adverb":"entirely","noun":"entirety"}', NULL, 2, 780),
(781, 'entitle', '/ɪnˈtaɪtəl/', 'verb', '{"zh-TW":["賦予權利；命名"],"en":["to give someone the right to do something"]}', NULL, 'be entitled to', '[{"en":"Full-time staff are entitled to 20 days of leave.","zh-TW":"全職員工有權享有20天假期。"},{"en":"The book is entitled ''Modern Management''.","zh-TW":"這本書名為《現代管理》。"}]', '{"noun":"entitlement","verb":"entitle","adjective":"entitled"}', NULL, 3, 781),
(782, 'entrepreneur', '/ˌɑːntrəprəˈnɜːr/', 'noun', '{"zh-TW":["企業家；創業者"],"en":["a person who starts and runs a business"]}', NULL, 'successful entrepreneur', '[{"en":"She is a successful entrepreneur in tech.","zh-TW":"她是科技領域的成功企業家。"},{"en":"Entrepreneurs drive innovation.","zh-TW":"企業家推動創新。"}]', '{"noun":"entrepreneur/entrepreneurship","adjective":"entrepreneurial"}', NULL, 4, 782),
(783, 'environment', '/ɪnˈvaɪrənmənt/', 'noun', '{"zh-TW":["環境"],"en":["the natural world; surrounding conditions"]}', NULL, 'work/business environment', '[{"en":"We must protect the environment.","zh-TW":"我們必須保護環境。"},{"en":"A positive work environment boosts morale.","zh-TW":"積極的工作環境提升士氣。"}]', '{"noun":"environment/environmentalist","adjective":"environmental","adverb":"environmentally"}', NULL, 4, 783),
(784, 'equal', '/ˈiːkwəl/', 'adjective / verb', '{"zh-TW":["相等的；等於"],"en":["the same in quantity, size, or value"]}', NULL, 'equal opportunity/rights', '[{"en":"All employees should receive equal pay for equal work.","zh-TW":"所有員工同工應同酬。"},{"en":"The total equals $5,000.","zh-TW":"總計等於5000美元。"}]', '{"noun":"equality","verb":"equal","adjective":"equal","adverb":"equally"}', NULL, 2, 784),
(785, 'equip', '/ɪˈkwɪp/', 'verb', '{"zh-TW":["裝備；配備"],"en":["to provide with necessary items or skills"]}', NULL, 'well-equipped / equip with', '[{"en":"The office is equipped with modern technology.","zh-TW":"辦公室配備了現代技術。"},{"en":"Training equips employees with new skills.","zh-TW":"培訓為員工配備新技能。"}]', '{"noun":"equipment","verb":"equip","adjective":"equipped"}', NULL, 2, 785),
(786, 'equity', '/ˈɛkwɪti/', 'noun', '{"zh-TW":["股權；權益"],"en":["the value of shares in a company","fairness"]}', NULL, 'private equity / home equity', '[{"en":"They raised capital through private equity.","zh-TW":"他們透過私募股權募集資金。"},{"en":"The company has strong brand equity.","zh-TW":"公司擁有強大的品牌價值。"}]', '{"noun":"equity","adjective":"equitable"}', NULL, 2, 786),
(787, 'equivalent', '/ɪˈkwɪvələnt/', 'adjective / noun', '{"zh-TW":["等同的；等價物","等同的；等價的"],"en":["equal in value, function, or meaning"]}', '{"prefix":{"text":"equi-","meaning":"equal (等同)"},"root":{"text":"val","meaning":"worth (價值)"},"suffix":{"text":"-ent","meaning":"being (…的)"},"logic":"價值等同的。"}', 'equivalent to; equivalent to / the equivalent of / roughly equivalent', '[{"en":"One mile is equivalent to 1.6 kilometers.","zh-TW":"一英里等於1.6公里。"},{"en":"There is no equivalent product on the market.","zh-TW":"市場上沒有同等的產品。"},{"en":"One mile is roughly equivalent to 1.6 kilometers.","zh-TW":"一英里大約等於1.6公里。"},{"en":"There is no equivalent word in English.","zh-TW":"英語中沒有等同的字。"}]', '{"noun":"equivalent/equivalence","adjective":"equivalent"}', NULL, 4, 787),
(788, 'erode', '/ɪˈroʊd/', 'verb', '{"zh-TW":["侵蝕；削弱"],"en":["to gradually wear away or diminish"]}', NULL, 'erode confidence/trust', '[{"en":"Competition has eroded profit margins.","zh-TW":"競爭侵蝕了利潤率。"},{"en":"Public trust in the brand has eroded.","zh-TW":"公眾對品牌的信任已被削弱。"}]', '{"noun":"erosion","verb":"erode"}', NULL, 2, 788),
(789, 'erosion', '/ɪˈroʊʒn/', 'noun', '{"zh-TW":["侵蝕"],"en":["the gradual wearing away of soil or rock"]}', '{"prefix":{"text":"e-","meaning":"away (離去)"},"root":{"text":"ros","meaning":"gnaw (啃蝕)"},"suffix":{"text":"-ion","meaning":"process (過程)"},"logic":"被啃蝕掉的過程，即「侵蝕」。"}', 'soil erosion / coastal erosion', '[{"en":"Soil erosion is a serious environmental problem.","zh-TW":"土壤侵蝕是嚴重的環境問題。"},{"en":"Heavy rain accelerates erosion.","zh-TW":"大雨加速侵蝕。"}]', '{"verb":"erode"}', NULL, 3, 789),
(790, 'error', '/ˈerər/', 'noun', '{"zh-TW":["錯誤；失誤"],"en":["a mistake; something incorrectly done"]}', NULL, 'human/clerical error', '[{"en":"The report contained several errors.","zh-TW":"報告中有幾處錯誤。"},{"en":"The error was caused by a software bug.","zh-TW":"錯誤是由軟體缺陷造成的。"}]', '{"noun":"error","adjective":"erroneous"}', NULL, 2, 790),
(791, 'escape', '/ɪˈskeɪp/', 'verb', '{"zh-TW":["逃脫；避免"],"en":["to get free from","to avoid something unpleasant"]}', NULL, 'escape route / narrow escape', '[{"en":"Know the escape routes in case of fire.","zh-TW":"了解火災時的逃生路線。"},{"en":"We had a narrow escape from the flooding.","zh-TW":"我們險些遭遇洪水。"}]', '{"verb":"escape","noun":"escape"}', NULL, 2, 791),
(792, 'essential', '/ɪˈsenʃəl/', 'adjective', '{"zh-TW":["必要的；基本的","必要的；本質的"],"en":["absolutely necessary; extremely important"]}', '{"root":{"text":"essent","meaning":"being/existence (存在)"},"suffix":{"text":"-ial","meaning":"relating to (相關的)"},"logic":"與存在本質相關的（不可缺少的）。"}', 'essential for/to; essential skills / essential information / absolutely essential', '[{"en":"Communication skills are essential for this role.","zh-TW":"溝通技能對這個職位是必要的。"},{"en":"It is essential to meet the deadline.","zh-TW":"在截止日期前完成是必要的。"},{"en":"Water is essential for life.","zh-TW":"水是生命所必需的。"},{"en":"Good communication skills are essential for this job.","zh-TW":"良好的溝通能力對這份工作至關重要。"}]', '{"noun":"essential/essentials","adjective":"essential","adverb":"essentially"}', NULL, 3, 792),
(793, 'establish', '/ɪˈstæblɪʃ/', 'verb', '{"zh-TW":["建立；確立","建立；設立"],"en":["to set up; to prove or show","to set up on a firm or permanent basis"]}', '{"prefix":{"text":"e-","meaning":"out (完全)"},"root":{"text":"stabl","meaning":"stable (穩定)"},"suffix":{"text":"-ish","meaning":"make (使)"},"logic":"使其穩固確立，即「建立」。"}', 'establish a company/reputation; establish a company / well-established', '[{"en":"The company was established in 1990.","zh-TW":"公司成立於1990年。"},{"en":"We need to establish clear guidelines.","zh-TW":"我們需要建立明確的指導方針。"},{"en":"They established a new policy for remote work.","zh-TW":"他們制定了新的遠端工作政策。"}]', '{"noun":"establishment","verb":"establish","adjective":"established"}', NULL, 3, 793),
(794, 'estimate', '/ˈestɪmeɪt/', 'verb / noun', '{"zh-TW":["估計；預算","估計"],"en":["to roughly calculate; an approximate judgment","to roughly calculate or judge the value of"]}', '{"root":{"text":"estim","meaning":"value (評價)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"做出評價，即「估計」。"}', 'rough/conservative estimate; rough estimate / cost estimate / estimate the cost', '[{"en":"We estimate the cost at $50,000.","zh-TW":"我們估計成本為5萬美元。"},{"en":"The initial estimate was too low.","zh-TW":"最初的估計太低了。"},{"en":"We estimate the project will cost $2 million.","zh-TW":"我們估計這個專案將花費200萬美元。"},{"en":"Can you give me a rough estimate?","zh-TW":"你能給我一個粗略的估計嗎？"}]', '{"noun":"estimate/estimation","verb":"estimate","adjective":"estimated","noun2":"estimation"}', NULL, 3, 794),
(795, 'evaluate', '/ɪˈvæljueɪt/', 'verb', '{"zh-TW":["評估；評價","評估"],"en":["to judge the value or quality of","to judge or determine the significance or value of"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"valu","meaning":"value (價值)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"衡量出價值來，即「評估」。"}', 'evaluate performance/options; evaluate performance / evaluate options', '[{"en":"We need to evaluate all options carefully.","zh-TW":"我們需要仔細評估所有選項。"},{"en":"Employee performance is evaluated annually.","zh-TW":"員工績效每年評估一次。"},{"en":"Teachers evaluate student performance regularly.","zh-TW":"老師定期評估學生表現。"},{"en":"We need to evaluate all the options.","zh-TW":"我們需要評估所有選項。"}]', '{"noun":"evaluation","verb":"evaluate"}', NULL, 3, 795),
(796, 'evening', '/ˈiːvnɪŋ/', 'noun', '{"zh-TW":["傍晚；晚上"],"en":["the part of the day between afternoon and night"]}', NULL, 'good evening / evening shift', '[{"en":"Good evening, everyone.","zh-TW":"大家晚上好。"},{"en":"She works the evening shift.","zh-TW":"她上晚班。"}]', '{"noun":"evening"}', NULL, 3, 796),
(797, 'eventually', '/ɪˈventʃuəli/', 'adverb', '{"zh-TW":["最終；終於"],"en":["in the end; after a period of time"]}', NULL, 'eventually lead to', '[{"en":"The negotiations eventually led to an agreement.","zh-TW":"談判最終達成了協議。"},{"en":"He eventually became the CEO.","zh-TW":"他最終成為了執行長。"}]', '{"adjective":"eventual","adverb":"eventually"}', NULL, 4, 797),
(798, 'evidence', '/ˈevɪdəns/', 'noun', '{"zh-TW":["證據；跡象","證據"],"en":["facts or signs showing something is true","facts or information indicating whether something is true"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"vid","meaning":"see (看)"},"suffix":{"text":"-ence","meaning":"state (狀態)"},"logic":"看得出來的事實，即「證據」。"}', 'provide/present evidence; scientific evidence / evidence suggests / lack of evidence', '[{"en":"There is evidence of improvement in sales.","zh-TW":"有銷售改善的證據。"},{"en":"The data provides evidence of a trend.","zh-TW":"數據提供了趨勢的證據。"},{"en":"There is no evidence to support this claim.","zh-TW":"沒有證據支持這項說法。"},{"en":"The evidence suggests a link between the two.","zh-TW":"證據顯示兩者之間有關聯。"}]', '{"noun":"evidence","adjective":"evident","adverb":"evidently"}', NULL, 3, 798),
(799, 'evolve', '/ɪˈvɑːlv/', 'verb', '{"zh-TW":["進化；發展"],"en":["to develop gradually over time"]}', NULL, 'evolve into/over time', '[{"en":"The company has evolved into a global brand.","zh-TW":"公司已發展成為全球品牌。"},{"en":"Consumer preferences evolve constantly.","zh-TW":"消費者偏好不斷演變。"}]', '{"noun":"evolution","verb":"evolve"}', NULL, 2, 799);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(800, 'exact', '/ɪɡˈzækt/', 'adjective', '{"zh-TW":["精確的；確切的"],"en":["completely accurate; precise"]}', NULL, 'exact amount/location', '[{"en":"The exact cost has not been determined yet.","zh-TW":"確切費用尚未確定。"},{"en":"Please provide the exact date.","zh-TW":"請提供確切日期。"}]', '{"adjective":"exact","adverb":"exactly"}', NULL, 2, 800),
(801, 'exam', '/ɪɡˈzæm/', 'noun', '{"zh-TW":["考試"],"en":["a formal test of knowledge"]}', NULL, 'take an exam / pass an exam', '[{"en":"I have three exams next week.","zh-TW":"我下週有三場考試。"},{"en":"She passed all her exams.","zh-TW":"她通過了所有考試。"}]', '{"noun2":"examination","noun3":"examiner"}', NULL, 1, 801),
(802, 'examine', '/ɪɡˈzæmɪn/', 'verb', '{"zh-TW":["檢查；審查"],"en":["to inspect closely; to test knowledge"]}', NULL, 'examine closely/carefully', '[{"en":"The auditor examined the financial records.","zh-TW":"審計師審查了財務記錄。"},{"en":"We need to examine this issue more closely.","zh-TW":"我們需要更仔細地審查這個問題。"}]', '{"noun":"examination/examiner","verb":"examine"}', NULL, 3, 802),
(803, 'example', '/ɪɡˈzæmpəl/', 'noun', '{"zh-TW":["例子；範例"],"en":["something typical of a group","a model to follow"]}', NULL, 'for example / set an example', '[{"en":"For example, we could reduce costs here.","zh-TW":"例如，我們可以在這裡降低成本。"},{"en":"She sets a good example for new staff.","zh-TW":"她為新員工樹立了好榜樣。"}]', '{"noun":"example","adjective":"exemplary","verb":"exemplify"}', NULL, 3, 803),
(804, 'exceed', '/ɪkˈsiːd/', 'verb', '{"zh-TW":["超過；超出","超過；超越"],"en":["to go beyond a limit or expectation","to go beyond a limit or standard"]}', '{"prefix":{"text":"ex-","meaning":"out (超出)"},"root":{"text":"ceed","meaning":"go (走)"},"logic":"走出去超越界限，即「超過」。"}', 'exceed expectations/limits; exceed expectations / exceed the limit', '[{"en":"Sales exceeded expectations this quarter.","zh-TW":"本季度銷售超出了預期。"},{"en":"Do not exceed the speed limit.","zh-TW":"不要超過速限。"},{"en":"Sales exceeded our expectations.","zh-TW":"銷售額超出了我們的預期。"}]', '{"adjective":"exceeding","adverb":"exceedingly"}', NULL, 2, 804),
(805, 'excellent', '/ˈeksələnt/', 'adjective', '{"zh-TW":["優秀的；極好的"],"en":["extremely good; outstanding"]}', NULL, 'excellent performance/service', '[{"en":"She received excellent feedback from clients.","zh-TW":"她收到了客戶的優秀評價。"},{"en":"The hotel provides excellent service.","zh-TW":"這家飯店提供優質服務。"}]', '{"noun":"excellence","adjective":"excellent"}', NULL, 3, 805),
(806, 'exception', '/ɪkˈsepʃən/', 'noun', '{"zh-TW":["例外"],"en":["something that does not follow a rule"]}', NULL, 'with the exception of / make an exception', '[{"en":"All staff must attend, with no exceptions.","zh-TW":"所有員工必須參加，沒有例外。"},{"en":"We can make an exception in this case.","zh-TW":"在這種情況下我們可以破例。"}]', '{"noun":"exception","adjective":"exceptional","adverb":"exceptionally"}', NULL, 3, 806),
(807, 'excess', '/ɪkˈses/', 'noun / adjective', '{"zh-TW":["過量；多餘的"],"en":["more than necessary or permitted"]}', NULL, 'in excess of / excess baggage', '[{"en":"Costs were in excess of the budget.","zh-TW":"費用超過了預算。"},{"en":"Excess inventory should be sold at a discount.","zh-TW":"多餘的庫存應打折出售。"}]', '{"noun":"excess","adjective":"excessive","adverb":"excessively"}', NULL, 2, 807),
(808, 'exchange', '/ɪksˈtʃeɪndʒ/', 'noun / verb', '{"zh-TW":["交換；兌換"],"en":["to give and receive; a place for trading","to give something and receive something in return"]}', '{"prefix":{"text":"ex-","meaning":"out (出)"},"root":{"text":"change","meaning":"change (改變)"},"logic":"把東西拿出來改變，即「交換」。"}', 'exchange rate / in exchange for; exchange rate / exchange information', '[{"en":"What is today''s exchange rate?","zh-TW":"今天的匯率是多少？"},{"en":"They exchanged business cards at the conference.","zh-TW":"他們在會議上交換了名片。"},{"en":"Can I exchange this shirt for a larger size?","zh-TW":"我可以把這件襯衫換大一號嗎？"},{"en":"They exchanged contact information.","zh-TW":"他們交換了聯絡資訊。"}]', '{"noun":"exchange","verb":"exchange","adjective":"exchangeable"}', NULL, 3, 808),
(809, 'excited', '/ɪkˈsaɪtɪd/', 'adjective', '{"zh-TW":["興奮的；激動的"],"en":["feeling great enthusiasm"]}', NULL, 'get excited / excited about', '[{"en":"We are excited about the new product launch.","zh-TW":"我們對新產品上市感到興奮。"},{"en":"The team is excited to start.","zh-TW":"團隊很期待開始。"}]', '{"adjective":"excited","verb":"excite","noun":"excitement","adjective2":"exciting"}', NULL, 3, 809),
(810, 'exclude', '/ɪkˈskluːd/', 'verb', '{"zh-TW":["排除；排斥"],"en":["to prevent from being included"]}', '{"prefix":{"text":"ex-","meaning":"out (出)"},"root":{"text":"clude","meaning":"close (關閉)"},"logic":"關在外面，即「排除」。"}', 'exclude from; exclude from / exclude the possibility', '[{"en":"Tax is excluded from the listed price.","zh-TW":"標示價格不含稅。"},{"en":"Some items are excluded from the warranty.","zh-TW":"某些物品不在保固範圍內。"},{"en":"The price excludes tax and delivery.","zh-TW":"價格不含稅和運費。"},{"en":"Don''t exclude anyone from the discussion.","zh-TW":"不要把任何人排除在討論之外。"}]', '{"noun":"exclusion","verb":"exclude","adjective":"exclusive"}', NULL, 3, 810),
(811, 'exclusive', '/ɪkˈskluːsɪv/', 'adjective', '{"zh-TW":["獨家的；專屬的"],"en":["limited to one person or group; high-end"]}', NULL, 'exclusive deal/rights', '[{"en":"We signed an exclusive distribution agreement.","zh-TW":"我們簽署了獨家經銷協議。"},{"en":"The hotel caters to an exclusive clientele.","zh-TW":"這家飯店專門服務高端客戶。"}]', '{"noun":"exclusivity","adjective":"exclusive","adverb":"exclusively"}', NULL, 3, 811),
(812, 'execute', '/ˈeksɪkjuːt/', 'verb', '{"zh-TW":["執行；實施"],"en":["to carry out a plan or action"]}', NULL, 'execute a plan/strategy', '[{"en":"The team executed the project flawlessly.","zh-TW":"團隊完美地執行了項目。"},{"en":"The strategy was well executed.","zh-TW":"該策略執行得很好。"}]', '{"noun":"execution/executive","verb":"execute"}', NULL, 3, 812),
(813, 'exempt', '/ɪɡˈzempt/', 'adjective / verb', '{"zh-TW":["免除的；豁免"],"en":["free from an obligation or liability"]}', NULL, 'exempt from tax/duty', '[{"en":"Non-profit organizations are exempt from taxes.","zh-TW":"非營利組織免稅。"},{"en":"Small businesses may be exempted from the regulation.","zh-TW":"小型企業可能免於遵守該法規。"}]', '{"noun":"exemption","verb":"exempt","adjective":"exempt"}', NULL, 2, 813),
(814, 'exercise', '/ˈeksərsaɪz/', 'noun / verb', '{"zh-TW":["運動；行使"],"en":["physical activity; to use a right or power"]}', NULL, 'exercise caution/authority', '[{"en":"Please exercise caution when handling chemicals.","zh-TW":"處理化學品時請小心謹慎。"},{"en":"Shareholders may exercise their voting rights.","zh-TW":"股東可以行使投票權。"}]', '{"noun":"exercise","verb":"exercise"}', NULL, 3, 814),
(815, 'exhaust', '/ɪɡˈzɔːst/', 'verb / noun', '{"zh-TW":["耗盡；排氣"],"en":["to use up completely; waste gases"]}', NULL, 'exhaust all options/resources', '[{"en":"We have exhausted all possible solutions.","zh-TW":"我們已經用盡了所有可能的解決方案。"},{"en":"Vehicle exhaust contributes to air pollution.","zh-TW":"汽車排氣造成空氣污染。"}]', '{"noun":"exhaustion/exhaust","verb":"exhaust","adjective":"exhausting/exhausted/exhaustive"}', NULL, 3, 815),
(816, 'exhibit', '/ɪɡˈzɪbɪt/', 'verb / noun', '{"zh-TW":["展覽；展示","展覽品；展覽"],"en":["to show publicly; a display","an object displayed in a museum","a public display of art or other items"]}', '{"prefix":{"text":"ex-","meaning":"out (外)"},"root":{"text":"hibit","meaning":"hold (持有)"},"logic":"拿出來展示，即「展覽」。"}', 'exhibit at a trade show; art exhibit / exhibit hall / on exhibit', '[{"en":"The company will exhibit at the trade fair.","zh-TW":"公司將在商展上展覽。"},{"en":"The museum has a new exhibit on technology.","zh-TW":"博物館有一個新的科技展覽。"},{"en":"The museum has a new dinosaur exhibit.","zh-TW":"博物館有新的恐龍展覽。"},{"en":"Her paintings are on exhibit at the gallery.","zh-TW":"她的畫作正在畫廊展出。"}]', '{"noun":"exhibit/exhibition/exhibitor","verb":"exhibit"}', NULL, 3, 816),
(817, 'exhibition', '/ˌɛksɪˈbɪʃən/', 'noun', '{"zh-TW":["展覽"],"en":["a public display of art or objects"]}', NULL, 'art exhibition / on exhibition', '[{"en":"The exhibition runs until March.","zh-TW":"展覽持續到三月。"},{"en":"We visited an art exhibition.","zh-TW":"我們參觀了一場藝術展覽。"}]', '{"verb":"exhibit","noun2":"exhibit"}', NULL, 4, 817),
(818, 'exist', '/ɪɡˈzɪst/', 'verb', '{"zh-TW":["存在"],"en":["to be real; to have actual being"]}', NULL, 'already exist / cease to exist', '[{"en":"The problem still exists.","zh-TW":"問題仍然存在。"},{"en":"Does a solution already exist?","zh-TW":"已經有解決方案了嗎？"}]', '{"verb":"exist","noun":"existence","adjective":"existing","adjective2":"existent"}', NULL, 2, 818),
(819, 'expand', '/ɪkˈspænd/', 'verb', '{"zh-TW":["擴展；擴大"],"en":["to increase in size, number, or importance"]}', '{"prefix":{"text":"ex-","meaning":"out (向外)"},"root":{"text":"pand","meaning":"spread (展開)"},"logic":"向外展開，即「擴展」。"}', 'expand operations/business; expand business / expand into new markets', '[{"en":"The company plans to expand into new markets.","zh-TW":"公司計劃擴展到新市場。"},{"en":"We need to expand our product range.","zh-TW":"我們需要擴大產品範圍。"},{"en":"The company plans to expand into Asia.","zh-TW":"公司計畫擴展到亞洲。"},{"en":"We need to expand our product range.","zh-TW":"我們需要擴大產品線。"}]', '{"noun":"expansion","verb":"expand"}', NULL, 2, 819),
(820, 'expect', '/ɪkˈspekt/', 'verb', '{"zh-TW":["期望；預期"],"en":["to believe something will happen"]}', NULL, 'expect + to / be expected to', '[{"en":"We expect revenue to increase next year.","zh-TW":"我們預期明年收入會增加。"},{"en":"Employees are expected to follow the dress code.","zh-TW":"員工被期望遵守服裝規定。"}]', '{"noun":"expectation","verb":"expect","adjective":"expected"}', NULL, 2, 820),
(821, 'expedite', '/ˈekspədaɪt/', 'verb', '{"zh-TW":["加快；促進"],"en":["to make a process happen more quickly"]}', NULL, 'expedite the process/delivery', '[{"en":"We can expedite shipping for an extra fee.","zh-TW":"我們可以加收費用加快出貨。"},{"en":"Please expedite the approval process.","zh-TW":"請加快審批流程。"}]', '{"verb":"expedite","adjective":"expedited"}', NULL, 3, 821),
(822, 'expenditure', '/ɪkˈspendɪtʃər/', 'noun', '{"zh-TW":["支出；開支"],"en":["the action of spending money; an amount spent"]}', NULL, 'capital/government expenditure', '[{"en":"Total expenditure exceeded the budget.","zh-TW":"總支出超過了預算。"},{"en":"Capital expenditure was reduced this year.","zh-TW":"今年資本支出減少了。"}]', '{"noun":"expenditure","verb":"expend"}', NULL, 4, 822),
(823, 'expense', '/ɪkˈspens/', 'noun', '{"zh-TW":["費用；開支"],"en":["the cost of something; money spent"]}', NULL, 'at the expense of / business expense', '[{"en":"Travel expenses will be reimbursed.","zh-TW":"差旅費用將報銷。"},{"en":"Profit should not come at the expense of quality.","zh-TW":"利潤不應以犧牲品質為代價。"}]', '{"noun":"expense","adjective":"expensive"}', NULL, 3, 823),
(824, 'experience', '/ɪkˈspɪriəns/', 'noun / verb', '{"zh-TW":["經驗；體驗"],"en":["knowledge gained through involvement; to encounter"]}', NULL, 'work/customer experience', '[{"en":"Do you have experience in project management?","zh-TW":"你有項目管理經驗嗎？"},{"en":"Customers experienced technical difficulties.","zh-TW":"客戶遇到了技術困難。"}]', '{"noun":"experience","verb":"experience","adjective":"experienced"}', NULL, 4, 824),
(825, 'experiment', '/ɪkˈsperɪmənt/', 'noun / verb', '{"zh-TW":["實驗；試驗"],"en":["a scientific test; to try something new"]}', NULL, 'conduct an experiment', '[{"en":"The team conducted an experiment to test the theory.","zh-TW":"團隊進行了實驗來測試理論。"},{"en":"We are experimenting with new marketing channels.","zh-TW":"我們正在嘗試新的行銷渠道。"}]', '{"noun":"experiment/experimentation","verb":"experiment","adjective":"experimental"}', NULL, 4, 825),
(826, 'expert', '/ˈekspɜːrt/', 'noun / adjective', '{"zh-TW":["專家；專業的"],"en":["a person with great knowledge in a subject"]}', NULL, 'industry/subject expert', '[{"en":"She is an expert in international trade.","zh-TW":"她是國際貿易專家。"},{"en":"We consulted an expert on tax law.","zh-TW":"我們諮詢了一位稅法專家。"}]', '{"noun":"expert/expertise","adjective":"expert"}', NULL, 2, 826),
(827, 'expire', '/ɪkˈspaɪər/', 'verb', '{"zh-TW":["到期；過期"],"en":["to come to the end of validity"]}', NULL, 'expire on/contract expires', '[{"en":"Your contract expires at the end of the month.","zh-TW":"你的合約月底到期。"},{"en":"The coupon expired yesterday.","zh-TW":"優惠券昨天過期了。"}]', '{"noun":"expiration/expiry","verb":"expire","adjective":"expired"}', NULL, 2, 827),
(828, 'explain', '/ɪkˈspleɪn/', 'verb', '{"zh-TW":["解釋；說明"],"en":["to make something clear"]}', NULL, 'explain how/why', '[{"en":"Can you explain the procedure?","zh-TW":"你能解釋一下流程嗎？"},{"en":"She explained why the project was delayed.","zh-TW":"她解釋了為什麼項目延遲了。"}]', '{"noun":"explanation","verb":"explain","adjective":"explanatory"}', NULL, 3, 828),
(829, 'explicit', '/ɪkˈsplɪsɪt/', 'adjective', '{"zh-TW":["明確的；清楚的"],"en":["stated clearly and in detail"]}', NULL, 'explicit instructions/consent', '[{"en":"The contract contains explicit terms.","zh-TW":"合約包含明確的條款。"},{"en":"You need explicit permission to proceed.","zh-TW":"你需要明確的許可才能繼續。"}]', '{"adjective":"explicit","adverb":"explicitly"}', NULL, 3, 829),
(830, 'exploit', '/ɪkˈsplɔɪt/', 'verb', '{"zh-TW":["利用；開發"],"en":["to make full use of; to use unfairly"]}', NULL, 'exploit resources/opportunities', '[{"en":"We should exploit this market opportunity.","zh-TW":"我們應該利用這個市場機會。"},{"en":"The company exploited cheap labor.","zh-TW":"公司剝削了廉價勞動力。"}]', '{"noun":"exploitation","verb":"exploit"}', NULL, 3, 830),
(831, 'explore', '/ɪkˈsplɔːr/', 'verb', '{"zh-TW":["探索；調查"],"en":["to examine or investigate thoroughly"]}', NULL, 'explore options/possibilities', '[{"en":"Let''s explore all available options.","zh-TW":"讓我們探索所有可用的選項。"},{"en":"The team explored new business models.","zh-TW":"團隊探索了新的商業模式。"}]', '{"noun":"exploration/explorer","verb":"explore","adjective":"exploratory"}', NULL, 3, 831),
(832, 'export', '/ˈekspɔːrt/', 'noun / verb', '{"zh-TW":["出口；輸出"],"en":["to sell goods to another country"]}', NULL, 'export goods/data', '[{"en":"Japan exports electronics worldwide.","zh-TW":"日本向全球出口電子產品。"},{"en":"Exports grew by 8% last year.","zh-TW":"去年出口增長了8%。"}]', '{"noun":"export/exporter","verb":"export"}', NULL, 2, 832),
(833, 'expose', '/ɪkˈspoʊz/', 'verb', '{"zh-TW":["暴露；揭發"],"en":["to make visible; to reveal","to make visible or reveal"]}', '{"prefix":{"text":"ex-","meaning":"out (出)"},"root":{"text":"pose","meaning":"put (放置)"},"logic":"把東西放到外面讓人看到，即「暴露」。"}', 'expose to risk/information; expose to / expose the truth', '[{"en":"Workers were exposed to harmful chemicals.","zh-TW":"工人暴露在有害化學品中。"},{"en":"The investigation exposed fraud in the company.","zh-TW":"調查揭發了公司的詐騙行為。"},{"en":"Children should not be exposed to violence.","zh-TW":"兒童不應暴露在暴力之下。"},{"en":"The journalist exposed the corruption scandal.","zh-TW":"記者揭發了貪腐醜聞。"}]', '{"noun":"exposure","verb":"expose","adjective":"exposed"}', NULL, 2, 833),
(834, 'extend', '/ɪkˈstend/', 'verb', '{"zh-TW":["延長；擴展","延伸；延長"],"en":["to make longer or larger"]}', '{"prefix":{"text":"ex-","meaning":"out (向外)"},"root":{"text":"tend","meaning":"stretch (伸展)"},"logic":"向外伸展，即「延伸」。"}', 'extend a deadline/contract; extend a deadline / extend an invitation', '[{"en":"Can we extend the deadline by one week?","zh-TW":"我們可以將截止日期延長一週嗎？"},{"en":"The company extended its operations to Asia.","zh-TW":"公司將業務擴展到亞洲。"},{"en":"Can we extend the deadline by one week?","zh-TW":"我們可以把截止期限延長一週嗎？"},{"en":"The road extends for 200 kilometers.","zh-TW":"這條路延伸了200公里。"}]', '{"noun":"extension","verb":"extend","adjective":"extensive/extended","adjective2":"extended"}', NULL, 2, 834),
(835, 'extensive', '/ɪkˈstensɪv/', 'adjective', '{"zh-TW":["廣泛的；大量的"],"en":["covering a large area or having great range","covering a large area or having a wide scope"]}', '{"prefix":{"text":"ex-","meaning":"out (向外)"},"root":{"text":"tens","meaning":"stretch (伸展)"},"suffix":{"text":"-ive","meaning":"having quality (具有…特質)"},"logic":"具有向外伸展特質的，即「廣泛的」。"}', 'extensive experience/research; extensive research / extensive experience / extensive damage', '[{"en":"She has extensive experience in finance.","zh-TW":"她有豐富的金融經驗。"},{"en":"Extensive research was conducted.","zh-TW":"進行了廣泛的研究。"},{"en":"She has extensive experience in marketing.","zh-TW":"她在行銷方面有豐富的經驗。"},{"en":"The storm caused extensive damage.","zh-TW":"暴風雨造成了大範圍的損害。"}]', '{"adjective":"extensive","adverb":"extensively","noun":"extent"}', NULL, 3, 835),
(836, 'external', '/ɪkˈstɜːrnəl/', 'adjective', '{"zh-TW":["外部的；外在的"],"en":["coming from outside"]}', NULL, 'external factors/audit', '[{"en":"External factors affected the company''s performance.","zh-TW":"外部因素影響了公司的績效。"},{"en":"An external audit will be conducted.","zh-TW":"將進行外部審計。"}]', '{"adjective":"external","adverb":"externally"}', NULL, 3, 836),
(837, 'extract', '/ɪkˈstrækt/', 'verb / noun', '{"zh-TW":["提取；摘錄"],"en":["to remove or obtain"]}', NULL, 'extract data/information', '[{"en":"We need to extract data from the system.","zh-TW":"我們需要從系統中提取數據。"},{"en":"The dentist extracted the tooth.","zh-TW":"牙醫拔了那顆牙。"}]', '{"noun":"extract/extraction","verb":"extract"}', NULL, 3, 837),
(838, 'extraordinary', '/ɪkˈstrɔːrdəneri/', 'adjective', '{"zh-TW":["非凡的；特別的"],"en":["very unusual or remarkable"]}', NULL, 'extraordinary achievement/circumstances', '[{"en":"She showed extraordinary leadership.","zh-TW":"她展示了非凡的領導力。"},{"en":"Due to extraordinary circumstances, the event was cancelled.","zh-TW":"由於特殊情況，活動被取消了。"}]', '{"adjective":"extraordinary","adverb":"extraordinarily"}', NULL, 5, 838),
(839, 'eye', '/aɪ/', 'noun', '{"zh-TW":["眼睛；注意"],"en":["the organ of sight","careful attention"]}', NULL, 'keep an eye on / eye-catching', '[{"en":"Keep an eye on the budget.","zh-TW":"留意預算。"},{"en":"The design is very eye-catching.","zh-TW":"這個設計非常吸睛。"}]', '{"noun":"eye","noun2":"eyesight"}', NULL, 1, 839),
(840, 'fabricate', '/ˈfæbrɪkeɪt/', 'verb', '{"zh-TW":["捏造；製造"],"en":["to invent false information; to construct"]}', NULL, 'fabricate evidence/a story', '[{"en":"He was accused of fabricating evidence.","zh-TW":"他被指控捏造證據。"},{"en":"The parts are fabricated in our factory.","zh-TW":"零件在我們工廠製造。"}]', '{"noun":"fabrication","verb":"fabricate"}', NULL, 3, 840),
(841, 'face', '/feɪs/', 'verb / noun', '{"zh-TW":["面對；面臨"],"en":["to confront; the front of something"]}', NULL, 'face challenges/problems', '[{"en":"The company faces several challenges.","zh-TW":"公司面臨幾項挑戰。"},{"en":"We must face the reality of budget cuts.","zh-TW":"我們必須面對預算削減的現實。"}]', '{"noun":"face","verb":"face"}', NULL, 1, 841),
(842, 'facilitate', '/fəˈsɪlɪteɪt/', 'verb', '{"zh-TW":["促進；使便利"],"en":["to make an action or process easier"]}', NULL, 'facilitate communication/growth', '[{"en":"Technology facilitates remote collaboration.","zh-TW":"技術促進了遠端協作。"},{"en":"The mediator facilitated the discussion.","zh-TW":"調解人促進了討論。"}]', '{"noun":"facilitation/facilitator","verb":"facilitate"}', NULL, 4, 842),
(843, 'facility', '/fəˈsɪləti/', 'noun', '{"zh-TW":["設施；場所"],"en":["a building or place for a particular purpose"]}', NULL, 'manufacturing/training facility', '[{"en":"The company opened a new manufacturing facility.","zh-TW":"公司開設了新的生產設施。"},{"en":"Our facilities are available for conferences.","zh-TW":"我們的設施可供會議使用。"}]', '{"noun":"facility"}', NULL, 3, 843),
(844, 'fact', '/fækt/', 'noun', '{"zh-TW":["事實"],"en":["something known to be true"]}', NULL, 'in fact / as a matter of fact', '[{"en":"In fact, sales increased by 20%.","zh-TW":"事實上，銷售增長了20%。"},{"en":"We need facts, not opinions.","zh-TW":"我們需要事實，不是意見。"}]', '{"noun":"fact","adjective":"factual","adverb":"factually"}', NULL, 1, 844),
(845, 'factor', '/ˈfæktər/', 'noun', '{"zh-TW":["因素；要素","因素"],"en":["a circumstance that contributes to a result"]}', '{"root":{"text":"fact","meaning":"make/do (做)"},"suffix":{"text":"-or","meaning":"that which (…的東西)"},"logic":"促成某事發生的東西，即「因素」。"}', 'key/determining factor; key factor / risk factor / contributing factor', '[{"en":"Cost is a major factor in the decision.","zh-TW":"成本是決策中的主要因素。"},{"en":"Several factors contributed to the failure.","zh-TW":"幾個因素導致了失敗。"},{"en":"Cost is an important factor in this decision.","zh-TW":"成本是這個決策中的重要因素。"},{"en":"Several factors contributed to the delay.","zh-TW":"多項因素導致了延遲。"}]', '{"noun":"factor","verb":"factor","adjective":"factorial"}', NULL, 2, 845),
(846, 'faculty', '/ˈfækəlti/', 'noun', '{"zh-TW":["全體教職員；院系"],"en":["the teaching staff of a university"]}', NULL, 'faculty member / faculty meeting', '[{"en":"The faculty voted on the proposal.","zh-TW":"教職員對提案進行了投票。"},{"en":"She''s a faculty member in the science department.","zh-TW":"她是理學院的教職員。"}]', NULL, NULL, 3, 846),
(847, 'fail', '/feɪl/', 'verb', '{"zh-TW":["失敗；未能"],"en":["to be unsuccessful; to neglect"]}', NULL, 'fail to meet/deliver', '[{"en":"The project failed to meet its objectives.","zh-TW":"該項目未能達成目標。"},{"en":"The business failed within two years.","zh-TW":"這家企業在兩年內倒閉了。"}]', '{"noun":"failure","verb":"fail"}', NULL, 1, 847),
(848, 'fair', '/fer/', 'adjective / noun', '{"zh-TW":["公平的；展覽會"],"en":["treating people equally; a commercial exhibition"]}', NULL, 'fair price/trade fair', '[{"en":"We offer fair prices to all customers.","zh-TW":"我們對所有客戶提供公平的價格。"},{"en":"We met potential clients at the trade fair.","zh-TW":"我們在商展上認識了潛在客戶。"}]', '{"noun":"fairness","adjective":"fair","adverb":"fairly"}', NULL, 1, 848),
(849, 'fall', '/fɔːl/', 'verb', '{"zh-TW":["下降；落下；秋天"],"en":["to drop down","to decrease","autumn"]}', NULL, 'fall behind / fall short', '[{"en":"Profits fell by 15% this quarter.","zh-TW":"本季利潤下降了15%。"},{"en":"The results fell short of expectations.","zh-TW":"結果未達預期。"}]', '{"verb":"fall","noun":"fall","noun2":"downfall"}', NULL, 1, 849);
