(902, 'fly', '/flaɪ/', 'verb', '{"zh-TW":["飛；搭飛機"],"en":["to move through the air","to travel by airplane"]}', NULL, 'fly abroad / fly business class', '[{"en":"I fly to Tokyo every month for work.","zh-TW":"我每個月飛東京出差。"},{"en":"Time flies when you are busy.","zh-TW":"忙碌時時間過得很快。"}]', '{"verb":"fly","noun":"flight","noun2":"flyer"}', NULL, 1, 902),
(903, 'focus', '/ˈfoʊkəs/', 'noun / verb', '{"zh-TW":["焦點；專注"],"en":["the center of attention; to concentrate"]}', NULL, 'focus on / main focus', '[{"en":"Our main focus is customer satisfaction.","zh-TW":"我們的主要焦點是客戶滿意度。"},{"en":"We need to focus on core business.","zh-TW":"我們需要專注於核心業務。"}]', '{"noun":"focus","verb":"focus","adjective":"focused"}', NULL, 2, 903),
(904, 'fog', '/fɒɡ/', 'noun', '{"zh-TW":["霧"],"en":["thick cloud of tiny water droplets near the ground"]}', '{"root":{"text":"fog","meaning":"mist (霧)"},"logic":"指地面附近的濃密水滴雲。"}', 'dense fog / fog advisory / foggy morning', '[{"en":"The fog reduced visibility to less than 50 meters.","zh-TW":"霧使能見度降到不足50公尺。"},{"en":"Drive carefully in the fog.","zh-TW":"在霧中小心開車。"}]', '{"adjective":"foggy"}', NULL, 1, 904),
(905, 'follow', '/ˈfɑːloʊ/', 'verb', '{"zh-TW":["遵循；跟隨"],"en":["to go after; to act according to"]}', NULL, 'follow instructions/guidelines', '[{"en":"Please follow the instructions carefully.","zh-TW":"請仔細遵循指示。"},{"en":"I''ll follow up with you next week.","zh-TW":"我下週會跟進。"}]', '{"noun":"follower/following","verb":"follow"}', NULL, 2, 905),
(906, 'food', '/fuːd/', 'noun', '{"zh-TW":["食物"],"en":["substances eaten for nutrition"]}', NULL, 'food industry / fast food', '[{"en":"The food industry is highly regulated.","zh-TW":"食品產業受到嚴格監管。"},{"en":"We provide food for the conference.","zh-TW":"我們為會議提供餐點。"}]', '{"noun":"food","noun2":"foodie"}', NULL, 1, 906),
