(908, 'forbid', '/fərˈbɪd/', 'verb', '{"zh-TW":["禁止"],"en":["to order someone not to do something"]}', NULL, 'strictly forbidden', '[{"en":"Smoking is forbidden in this building.","zh-TW":"這棟建築內禁止吸菸。"},{"en":"Company policy forbids personal use of equipment.","zh-TW":"公司政策禁止私人使用設備。"}]', '{"verb":"forbid","adjective":"forbidden"}', NULL, 2, 908),
(909, 'force', '/fɔːrs/', 'noun / verb', '{"zh-TW":["力量；迫使"],"en":["strength or power; to make someone do something"]}', NULL, 'by force / in force', '[{"en":"The new regulations are now in force.","zh-TW":"新法規現已生效。"},{"en":"Budget cuts forced the company to downsize.","zh-TW":"預算削減迫使公司裁員。"}]', '{"noun":"force","verb":"force","adjective":"forceful"}', NULL, 2, 909),
(910, 'forecast', '/ˈfɔːrkæst/', 'noun / verb', '{"zh-TW":["預測；預報","預報；預測"],"en":["a prediction about future events","a prediction of future events, especially weather"]}', '{"prefix":{"text":"fore-","meaning":"before (預先)"},"root":{"text":"cast","meaning":"throw/plan (投/計劃)"},"logic":"預先計劃推測，即「預報」。"}', 'sales/weather forecast; weather forecast / sales forecast', '[{"en":"The sales forecast looks promising.","zh-TW":"銷售預測看起來很樂觀。"},{"en":"Analysts forecast steady growth next year.","zh-TW":"分析師預測明年穩定增長。"},{"en":"The forecast says it will rain tomorrow.","zh-TW":"天氣預報說明天會下雨。"},{"en":"The economic forecast looks positive.","zh-TW":"經濟預測看起來樂觀。"}]', '{"noun":"forecast","verb":"forecast"}', NULL, 3, 910),
