(1306, 'manifest', '/ˈmænɪfest/', 'verb, adjective', '{"zh-TW":["表明；顯示","明顯的"],"en":["to show or demonstrate clearly","obvious"]}', NULL, 'manifest itself / manifest in', '[{"en":"Stress can manifest itself in various physical symptoms.","zh-TW":"壓力可以通過各種身體症狀表現出來。"},{"en":"The problems manifested during the testing phase.","zh-TW":"問題在測試階段顯現出來。"}]', '{"noun":"manifestation","verb":"manifest","adjective":"manifest"}', NULL, 3, 1306),
(1307, 'manipulate', '/məˈnɪpjuleɪt/', 'verb', '{"zh-TW":["操縱；操控"],"en":["to control or influence skillfully, often unfairly"]}', NULL, 'manipulate data/figures/people', '[{"en":"He was accused of manipulating financial data.","zh-TW":"他被指控操縱財務數據。"},{"en":"The software allows you to manipulate images easily.","zh-TW":"該軟體允許你輕鬆操作圖像。"}]', '{"noun":"manipulation, manipulator","verb":"manipulate","adjective":"manipulative"}', NULL, 4, 1307),
(1308, 'manner', '/ˈmænər/', 'noun', '{"zh-TW":["方式；態度；禮貌"],"en":["the way something is done; behavior"]}', NULL, 'in a professional manner / in this manner', '[{"en":"Please handle all complaints in a professional manner.","zh-TW":"請以專業的方式處理所有投訴。"},{"en":"His manner was calm and reassuring.","zh-TW":"他的態度冷靜而令人放心。"}]', '{"noun":"manner, manners","adjective":"mannered"}', NULL, 2, 1308),
(1309, 'manual', '/ˈmænjuəl/', 'noun, adjective', '{"zh-TW":["手冊；說明書","手動的；體力的"],"en":["a handbook; a book of instructions","done by hand; physical"]}', NULL, 'user/instruction manual / manual labor', '[{"en":"Please refer to the user manual for setup instructions.","zh-TW":"請參閱使用手冊了解安裝說明。"},{"en":"The process was switched from manual to automated.","zh-TW":"流程從手動改為自動化。"}]', '{"noun":"manual","adjective":"manual","adverb":"manually"}', NULL, 2, 1309),
