(1311, 'manuscript', '/ˈmænjuskrɪpt/', 'noun', '{"zh-TW":["手稿；原稿"],"en":["an author''s text that has not yet been published"]}', NULL, 'submit a manuscript / manuscript review', '[{"en":"The author submitted the manuscript to the publisher.","zh-TW":"作者向出版社提交了手稿。"},{"en":"The manuscript was reviewed by three experts.","zh-TW":"手稿由三位專家審閱。"}]', '{"noun":"manuscript"}', NULL, 4, 1311),
(1312, 'map', '/mæp/', 'noun', '{"zh-TW":["地圖；規劃"],"en":["a drawing of an area","to plan in detail"]}', NULL, 'road map / map out', '[{"en":"We mapped out our strategy for next year.","zh-TW":"我們規劃了明年的策略。"},{"en":"Here is the road map for the project.","zh-TW":"這是專案的路線圖。"}]', '{"noun":"map","verb":"map","noun2":"mapping"}', NULL, 1, 1312),
(1313, 'marathon', '/ˈmærəθɒn/', 'noun', '{"zh-TW":["馬拉松"],"en":["a long-distance running race of 42.195 km"]}', NULL, 'run a marathon / marathon runner', '[{"en":"She completed her first marathon.","zh-TW":"她完成了她的第一場馬拉松。"},{"en":"Training for a marathon takes months.","zh-TW":"馬拉松訓練需要數月時間。"}]', NULL, NULL, 3, 1313),
