(1315, 'maritime', '/ˈmærɪtaɪm/', 'adjective', '{"zh-TW":["海事的；海運的"],"en":["relating to the sea or shipping"]}', NULL, 'maritime law/industry/trade', '[{"en":"Maritime trade accounts for 80% of global commerce.","zh-TW":"海運貿易佔全球商業的80%。"},{"en":"Maritime law governs shipping disputes.","zh-TW":"海事法管轄航運糾紛。"}]', '{"noun":"maritime","adjective":"maritime"}', NULL, 3, 1315),
(1316, 'mark', '/mɑːrk/', 'noun', '{"zh-TW":["標記；分數；里程碑"],"en":["a sign or symbol","a target or level"]}', NULL, 'hit the mark / benchmark', '[{"en":"The presentation hit the mark.","zh-TW":"報告切中要點。"},{"en":"We passed the one million mark.","zh-TW":"我們突破了一百萬大關。"}]', '{"noun":"mark","verb":"mark","noun2":"marker","noun3":"marking","noun4":"trademark"}', NULL, 1, 1316),
(1317, 'market', '/ˈmɑːrkɪt/', 'noun, verb', '{"zh-TW":["市場","推銷；銷售"],"en":["a place where goods are sold; demand for goods","to advertise and sell"]}', NULL, 'market share / target market / market research', '[{"en":"We need to conduct market research before launching.","zh-TW":"我們需要在推出前進行市場調查。"},{"en":"The product was successfully marketed to young professionals.","zh-TW":"該產品成功地向年輕專業人士推銷。"}]', '{"noun":"market, marketing, marketer","verb":"market","adjective":"marketable"}', NULL, 2, 1317),
(1318, 'markup', '/ˈmɑːrkʌp/', 'noun', '{"zh-TW":["加價；標記"],"en":["the amount added to cost price for profit"]}', NULL, 'price markup / markup percentage', '[{"en":"Retailers typically apply a 50% markup on wholesale prices.","zh-TW":"零售商通常在批發價上加價50%。"},{"en":"The markup on luxury goods is significantly higher.","zh-TW":"奢侈品的加價幅度明顯更高。"}]', '{"noun":"markup","verb":"mark up"}', NULL, 2, 1318),
(1319, 'marry', '/ˈmæri/', 'verb', '{"zh-TW":["結婚"],"en":["to become the spouse of someone"]}', NULL, 'get married / married life', '[{"en":"They got married last summer.","zh-TW":"他們去年夏天結婚了。"},{"en":"She is married with two children.","zh-TW":"她已婚並育有兩個孩子。"}]', '{"verb":"marry","noun":"marriage","adjective":"married","adjective2":"unmarried"}', NULL, 2, 1319),
(1320, 'massive', '/ˈmæsɪv/', 'adjective', '{"zh-TW":["大量的；巨大的"],"en":["extremely large or serious"]}', NULL, 'massive investment/growth/change', '[{"en":"The project requires a massive investment.","zh-TW":"該項目需要大量投資。"},{"en":"There has been massive growth in online shopping.","zh-TW":"網上購物出現了大幅增長。"}]', '{"noun":"mass","adjective":"massive","adverb":"massively"}', NULL, 3, 1320),
