(1335, 'mediate', '/ˈmiːdieɪt/', 'verb', '{"zh-TW":["調解；斡旋"],"en":["to try to end a disagreement between parties"]}', NULL, 'mediate a dispute / mediate between', '[{"en":"A neutral party was brought in to mediate the dispute.","zh-TW":"引入了中立方來調解爭端。"},{"en":"She mediated between management and the union.","zh-TW":"她在管理層和工會之間進行調解。"}]', '{"noun":"mediation, mediator","verb":"mediate"}', NULL, 3, 1335),
(1336, 'mediocre', '/ˌmiːdiˈoʊkər/', 'adjective', '{"zh-TW":["平庸的；普通的"],"en":["of only average quality; not very good"]}', NULL, 'mediocre performance/results/quality', '[{"en":"Mediocre performance will not be tolerated.","zh-TW":"平庸的表現將不被容忍。"},{"en":"The product received mediocre reviews.","zh-TW":"該產品獲得了普通的評價。"}]', '{"noun":"mediocrity","adjective":"mediocre"}', NULL, 3, 1336),
