(1392, 'municipal', '/mjuːˈnɪsɪpəl/', 'adjective', '{"zh-TW":["市政的","市政的；地方政府的"],"en":["relating to a city or town government"]}', NULL, 'municipal government / municipal court; municipal government/services/bonds', '[{"en":"The municipal government approved the plan.","zh-TW":"市政府批准了這項計畫。"},{"en":"Municipal elections are held every four years.","zh-TW":"市政選舉每四年舉行一次。"},{"en":"Municipal bonds are a popular investment option.","zh-TW":"市政債券是一種受歡迎的投資選擇。"},{"en":"The municipal government approved the new park.","zh-TW":"市政府批准了新公園的建設。"}]', '{"noun":"municipality","adjective":"municipal"}', NULL, 3, 1392),
(1393, 'mural', '/ˈmjʊrəl/', 'noun', '{"zh-TW":["壁畫"],"en":["a painting done directly on a wall"]}', '{"root":{"text":"mur","meaning":"wall (牆)"},"suffix":{"text":"-al","meaning":"relating to (相關的)"},"logic":"與牆相關的繪畫，即「壁畫」。"}', 'paint a mural / street mural', '[{"en":"The artist painted a mural on the building.","zh-TW":"藝術家在建築物上畫了一幅壁畫。"},{"en":"The city is famous for its colorful murals.","zh-TW":"這座城市以色彩繽紛的壁畫聞名。"}]', '{"noun":"muralist"}', NULL, 2, 1393),
(1394, 'music', '/ˈmjuːzɪk/', 'noun', '{"zh-TW":["音樂"],"en":["sounds arranged in a pleasing way"]}', NULL, 'background music / music industry', '[{"en":"The music industry has changed dramatically.","zh-TW":"音樂產業已發生了巨大變化。"},{"en":"Soft background music plays in the store.","zh-TW":"店裡播放著柔和的背景音樂。"}]', '{"noun":"music","noun2":"musician","adjective":"musical"}', NULL, 2, 1394),
(1395, 'mutual', '/ˈmjuːtʃuəl/', 'adjective', '{"zh-TW":["相互的；共同的"],"en":["shared by two or more parties"]}', NULL, 'mutual agreement/benefit/respect / mutual fund', '[{"en":"The contract was terminated by mutual agreement.","zh-TW":"合同經雙方協議終止。"},{"en":"Mutual respect is the foundation of good teamwork.","zh-TW":"相互尊重是良好團隊合作的基礎。"}]', '{"noun":"mutuality","adjective":"mutual","adverb":"mutually"}', NULL, 2, 1395),
(1396, 'name', '/neɪm/', 'noun', '{"zh-TW":["名字；名稱"],"en":["a word used to identify a person or thing"]}', NULL, 'brand name / in the name of', '[{"en":"What is your company name?","zh-TW":"你的公司名稱是什麼？"},{"en":"The account is in the name of the director.","zh-TW":"帳戶是以主管的名義開的。"}]', '{"noun":"name","verb":"name","adjective":"named","adverb":"namely"}', NULL, 1, 1396),
(1397, 'narrow', '/ˈnæroʊ/', 'adjective', '{"zh-TW":["狹窄的","有限的；勉強的"],"en":["small in width","limited in range"]}', '{"root":{"text":"narr","meaning":"tight (緊的)"}}', 'narrow down / narrow margin / narrow escape', '[{"en":"The road was too narrow for two cars.","zh-TW":"這條路太窄了，容不下兩輛車。"},{"en":"We need to narrow down the candidates.","zh-TW":"我們需要縮小候選人範圍。"}]', '{"verb":"narrow","adverb":"narrowly","noun":"narrowness"}', NULL, 2, 1397),
(1398, 'nature', '/ˈneɪtʃər/', 'noun', '{"zh-TW":["自然；本質"],"en":["the physical world","the basic character of something"]}', NULL, 'by nature / nature of business', '[{"en":"What is the nature of your business?","zh-TW":"你的業務性質是什麼？"},{"en":"He is competitive by nature.","zh-TW":"他天性好勝。"}]', '{"noun":"nature","adjective":"natural","adverb":"naturally"}', NULL, 2, 1398),
(1399, 'near', '/nɪr/', 'preposition', '{"zh-TW":["靠近；附近"],"en":["close to in distance or time"]}', NULL, 'near future / nearby', '[{"en":"Changes will happen in the near future.","zh-TW":"改變將在不久的將來發生。"},{"en":"Is there a restaurant nearby?","zh-TW":"附近有餐廳嗎？"}]', '{"preposition":"near","adjective":"near","adverb":"nearly","adjective2":"nearby"}', NULL, 1, 1399);
