(1644, 'proud', '/praʊd/', 'adjective', '{"zh-TW":["驕傲的；自豪的"],"en":["feeling pleasure about one''s achievements","feeling deep pleasure from one''s own achievements"]}', '{"root":{"text":"proud","meaning":"valiant (英勇)"},"logic":"源自古法語 prud（英勇的），後指對自身感到光榮。"}', 'proud of / proud moment', '[{"en":"We are proud of our team''s achievement.","zh-TW":"我們為團隊的成就感到自豪。"},{"en":"This is a proud moment for the company.","zh-TW":"這是公司引以為傲的時刻。"},{"en":"Her parents are proud of her accomplishments.","zh-TW":"她的父母為她的成就感到驕傲。"},{"en":"It was a proud moment for the whole team.","zh-TW":"這是全隊引以為傲的時刻。"}]', '{"adjective":"proud","noun":"pride","adverb":"proudly"}', NULL, 2, 1644),
(1645, 'prove', '/pruːv/', 'verb', '{"zh-TW":["證明；證實"],"en":["to show that something is true"]}', NULL, 'prove that / prove to be / prove successful', '[{"en":"The data proved our hypothesis correct.","zh-TW":"數據證明我們的假設正確。"},{"en":"The investment proved to be profitable.","zh-TW":"投資被證明是有利可圖的。"}]', '{"noun":"proof","adjective":"proven"}', NULL, 2, 1645),
(1646, 'provide', '/prəˈvaɪd/', 'verb', '{"zh-TW":["提供"],"en":["to give or supply something"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"vide","meaning":"see (看)"}}', 'provide services / provide information / provide support', '[{"en":"We provide 24/7 customer support.","zh-TW":"我們提供全天候客服支援。"},{"en":"The report provides useful information.","zh-TW":"報告提供了有用資訊。"}]', '{"noun":"provider, provision","adjective":"provided"}', NULL, 3, 1646),
(1647, 'provision', '/prəˈvɪʒən/', 'noun', '{"zh-TW":["規定；條款","供應"],"en":["a condition in a law or agreement","the act of providing"]}', '{"prefix":{"text":"pro-","meaning":"forward"},"root":{"text":"vis","meaning":"see (看)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'make provisions for / under the provisions of / provision of services', '[{"en":"The contract includes a provision for early termination.","zh-TW":"合約包含提前終止的條款。"},{"en":"Make provisions for unexpected expenses.","zh-TW":"為意外開支做好準備。"}]', '{"adjective":"provisional","verb":"provision"}', NULL, 3, 1647),
(1648, 'provoke', '/prəˈvoʊk/', 'verb', '{"zh-TW":["激起；引發"],"en":["to cause a reaction; to anger"]}', '{"prefix":{"text":"pro-","meaning":"forth"},"root":{"text":"voke","meaning":"call (召喚)"}}', 'provoke a response / provoke debate / provoke anger', '[{"en":"The announcement provoked strong reactions.","zh-TW":"公告引起了強烈反應。"},{"en":"His comments provoked a heated debate.","zh-TW":"他的評論引發了激烈辯論。"}]', '{"noun":"provocation","adjective":"provocative"}', NULL, 3, 1648),
(1649, 'public', '/ˈpʌblɪk/', 'adjective', '{"zh-TW":["公共的；公眾的"],"en":["relating to people in general"]}', '{"root":{"text":"publ","meaning":"people (人民)"}}', 'public sector / public opinion / go public', '[{"en":"The company plans to go public next year.","zh-TW":"公司計劃明年上市。"},{"en":"Public transportation is convenient here.","zh-TW":"這裡的公共交通很方便。"}]', '{"noun":"public, publicity","adverb":"publicly","verb":"publicize"}', NULL, 2, 1649);
